#!/bin/bash
# ============================================================
# run_cpu.sh — 08 dispersion prism (BK7/SF1 n(λ) wavelength dispersion), CPU(Geant4) only
#   Runs the profile test (CPU z/x profile).
#   TESTS default = "profile". (The xze map for the GPU rainbow is generated by GPU only — run_gpu.sh)
#   photons: PHOTONS=10000000 ./run_cpu.sh  (default 5M; injects NumberOfHistoriesInRun. CPU is integer·≤2.15B·slow)
#   thread: THREADS=30 ./run_cpu.sh   (default 20=config value; overrides NumberOfThreads via sed)
#   override: TOPAS=/path/topas-gpu ./run_cpu.sh   (patched topas-gpu required)
#   CSV → results/disp_prof_CPU.csv. After both (gpu+cpu) have run, make the figure with:
#         python3 plot.py
# ============================================================
cd "$(dirname "$0")"

. ../common/topas_env.sh
TESTS="${1:-${TESTS:-profile}}"
THREADS="${THREADS:-20}"
PHOTONS="${PHOTONS:-5000000}"   # CPU photon count = NumberOfHistoriesInRun (integer; >2.15B not allowed, slow)
export G4TRACE_DIR=OFF   # g4trace disk logging off (if not disabled CPU is tens to hundreds of times slower; result is bit-identical)

[ -x "$TOPAS" ] || { echo "ERROR: TOPAS binary not found: $TOPAS"; exit 1; }
mkdir -p results
cd configs

echo "=== 08 CPU dispersion prism  (tests: $TESTS, photons=$PHOTONS, T=$THREADS) ==="
printf "%-10s %16s\n" "test" "Execution(s)"
for t in $TESTS; do
  case "$t" in
    profile) cfg="dispersion_profile_cpu.txt" ;;
    *) printf "%-10s %16s\n" "$t" "[unknown test]"; continue ;;
  esac
  [ -f "$cfg" ] || { printf "%-10s %16s\n" "$t" "[no config]"; continue; }
  tmp=".tmp_${t}_cpu.txt"
  sed -e "s|^i:Ts/NumberOfThreads = .*|i:Ts/NumberOfThreads = ${THREADS}|" \
      -e "s|^i:So/Beam/NumberOfHistoriesInRun = .*|i:So/Beam/NumberOfHistoriesInRun = ${PHOTONS}|" \
      "$cfg" > "$tmp"
  G4TRACE_DIR=OFF "$TOPAS" "$tmp" > "../results/run_${t}_cpu.log" 2>&1
  exec_t=$(grep "Execution:" "../results/run_${t}_cpu.log" | grep -oE "Real=[0-9.]+s" | head -1 | sed 's/Real=//;s/s//')
  printf "%-10s %16s\n" "$t" "${exec_t:-FAILED}"
  rm -f "$tmp"
done
echo "CSV: benchmark/08_dispersion_prism/results/disp_prof_CPU.csv"
echo "figure (after running both gpu+cpu): python3 plot.py"
